//! The Rust write-back gives the same XML as web/js/ooxml.js on every case in
//! cases.json (generated by test/writeback-cases.mjs from the fixtures).

use babel_docx::tree::{Kind, Tree};
use babel_docx::{apply_paragraph, Info, Templates, Token};
use serde::Deserialize;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    file: String,
    pid: String,
    variant: String,
    before: String,
    tokens: Vec<Token>,
    text_runs: Vec<String>,
    atoms: Vec<String>,
    after: String,
}

/// The same XML whatever the serialiser: attributes sorted, text as is.
fn canonical(xml: &str) -> String {
    let t = Tree::parse(xml).unwrap();
    let mut out = String::new();
    write(&t, t.root, &mut out);
    out
}

fn write(t: &Tree, id: usize, out: &mut String) {
    match t.kind(id) {
        Kind::Text(s) => out.push_str(&format!("{s:?}")),
        Kind::Raw(s) => out.push_str(s),
        Kind::Element { name, attrs } => {
            let mut a = attrs.clone();
            a.sort();
            out.push_str(&format!("<{name} {a:?}>"));
            for &c in t.children(id) {
                write(t, c, out);
            }
            out.push_str(&format!("</{name}>"));
        }
    }
}

#[test]
fn matches_the_javascript_write_back() {
    let cases: Vec<Case> = serde_json::from_str(include_str!("cases.json")).unwrap();
    assert!(cases.len() > 1000);
    // The comparison sees edits: most cases change the paragraph.
    let changed = cases.iter().filter(|c| canonical(&c.before) != canonical(&c.after)).count();
    assert!(changed > 1000, "only {changed} cases change anything");
    let mut failed = vec![];
    for c in &cases {
        let mut info = Info { text_runs: c.text_runs.clone(), atoms: c.atoms.iter().cloned().collect() };
        let got = apply_paragraph(&c.before, &c.tokens, &mut info, &mut Templates::new()).unwrap();
        if canonical(&got) != canonical(&c.after) {
            failed.push((c, got));
        }
    }
    if let Some((c, got)) = failed.first() {
        panic!(
            "{} of {} cases differ; first: {} {} {}\n--- javascript\n{}\n--- rust\n{}",
            failed.len(),
            cases.len(),
            c.file,
            c.pid,
            c.variant,
            c.after,
            got
        );
    }
}
